#include "CSSBC_System.h"
#include <algorithm>
namespace cssbc{bool CSSBCSystem::CanPurchase(SupportTier t,int money,int dead)const{auto&c=kSupport[(size_t)t];return money>=c.price&&dead>=c.deadAlliesRequired;}bool CSSBCSystem::RequestSupport(SupportTier t,int id,int money,int dead,SupportOrder&o)const{if(!CanPurchase(t,money,dead))return false;auto&c=kSupport[(size_t)t];o={t,id,c.price,dead};return true;}float CSSBCSystem::RetreatProbability(const Traits&t,float hp,float allies,float pressure)const{return std::clamp(.08f+(1-t.courage)*.3f+(1-t.teamwork)*.12f+(1-std::clamp(hp,0.f,1.f))*.3f+std::clamp(pressure,0.f,1.f)*.22f-std::clamp(allies,0.f,4.f)*.07f,.02f,.85f);}float CSSBCSystem::CoverReward(float sec,int allies)const{return std::max(0.f,sec)*std::max(0,allies)*2.f;}}